-- >>> v_admin_users.sql
-- v_admin_users
-- Instance-scoped user view for admin panel. Unlike v_users, this is NOT
-- workspace-scoped and includes all users regardless of membership.
CREATE OR REPLACE VIEW v_admin_users AS
SELECT
  u.id,
  u.public_id,
  u.email,
  u.display_name,
  u.avatar_url,
  u.locale,
  u.timezone,
  u.country,
  u.last_login_at,
  u.email_verified_at,
  u.enabled,
  u.created_at,
  u.updated_at,
  (SELECT COUNT(*) FROM workspace_members wm
     WHERE wm.user_id = u.id AND wm.enabled = TRUE) AS workspace_count,
  EXISTS(SELECT 1 FROM instance_admins ia
     WHERE ia.user_id = u.id AND ia.enabled = TRUE
       AND ia.revoked_at IS NULL) AS is_instance_admin
FROM users u;

-- >>> v_audit_recent.sql
-- v_audit_recent
-- Recent audit events projected for the admin UI. api_key values are
-- never present here; metadata_json is already redacted at write time.
CREATE OR REPLACE VIEW v_audit_recent AS
SELECT
  al.workspace_id,
  al.public_id,
  actor.public_id AS actor_user_public_id,
  actor.display_name AS actor_display_name,
  al.action,
  al.resource_type,
  al.resource_public_id,
  al.ip_address,
  al.user_agent,
  al.metadata_json,
  al.occurred_at
FROM audit_logs al
INNER JOIN workspaces w
  ON w.id = al.workspace_id AND w.enabled = TRUE
LEFT JOIN users actor
  ON actor.id = al.actor_user_id AND actor.enabled = TRUE
WHERE al.enabled = TRUE;

-- >>> v_inbox.sql
-- v_inbox
-- Aggregated inbox: signals that have arrived in a workspace with optional
-- task linkage. Consumers filter by workspace_id and archive/snooze state.
CREATE OR REPLACE VIEW v_inbox AS
SELECT
  s.workspace_id,
  w.public_id AS workspace_public_id,
  s.public_id,
  t.public_id AS task_public_id,
  t.title AS task_title,
  s.source,
  s.kind,
  s.external_id,
  s.payload_json,
  s.received_at,
  s.updated_at,
  s.created_at
FROM signals s
INNER JOIN workspaces w
  ON w.id = s.workspace_id AND w.enabled = TRUE
LEFT JOIN tasks t
  ON t.id = s.task_id AND t.enabled = TRUE
WHERE s.enabled = TRUE;

-- >>> v_instance_audit_logs.sql
-- v_instance_audit_logs
-- Instance-wide audit log joined with actor user and optional workspace.
CREATE OR REPLACE VIEW v_instance_audit_logs AS
SELECT
  ial.public_id,
  actor.public_id   AS actor_user_public_id,
  actor.display_name AS actor_display_name,
  ial.action,
  ws.public_id      AS target_workspace_public_id,
  ws.name           AS target_workspace_name,
  ial.target_resource_type,
  ial.target_resource_public_id,
  ial.ip_address,
  ial.user_agent,
  ial.payload_json,
  ial.occurred_at
FROM instance_audit_logs ial
LEFT JOIN users actor ON actor.id = ial.actor_user_id
LEFT JOIN workspaces ws ON ws.id = ial.target_workspace_id
WHERE ial.enabled = TRUE;

-- >>> v_my_tasks.sql
-- v_my_tasks
-- Tasks where a user is attached as an actor. Consumers filter on
-- user_public_id in addition to workspace_id.
CREATE OR REPLACE VIEW v_my_tasks AS
SELECT
  t.workspace_id,
  t.public_id,
  u.public_id AS user_public_id,
  p.public_id AS project_public_id,
  p.name AS project_name,
  t.title,
  t.derived_state,
  t.priority,
  t.due_on,
  t.started_on,
  t.event_on,
  a.role AS actor_role,
  t.updated_at,
  t.created_at
FROM task_actors a
INNER JOIN tasks t
  ON t.id = a.task_id AND t.enabled = TRUE
INNER JOIN projects p
  ON p.id = t.project_id AND p.enabled = TRUE
INNER JOIN users u
  ON u.id = a.user_id AND u.enabled = TRUE
INNER JOIN workspaces w
  ON w.id = t.workspace_id AND w.enabled = TRUE
WHERE a.enabled = TRUE;

-- >>> v_project_stats.sql
-- v_project_stats
-- Aggregated task counts per project, grouped by derived_state.
CREATE OR REPLACE VIEW v_project_stats AS
SELECT
  p.workspace_id,
  p.public_id,
  p.name,
  COUNT(t.id) AS task_count,
  SUM(CASE WHEN t.derived_state = 'open' THEN 1 ELSE 0 END) AS open_count,
  SUM(CASE WHEN t.derived_state = 'waiting' THEN 1 ELSE 0 END) AS waiting_count,
  SUM(CASE WHEN t.derived_state = 'review' THEN 1 ELSE 0 END) AS review_count,
  SUM(CASE WHEN t.derived_state = 'done' THEN 1 ELSE 0 END) AS done_count,
  SUM(CASE WHEN t.derived_state = 'cancelled' THEN 1 ELSE 0 END) AS cancelled_count,
  MAX(t.updated_at) AS last_task_updated_at
FROM projects p
LEFT JOIN tasks t
  ON t.project_id = p.id AND t.enabled = TRUE
INNER JOIN workspaces w
  ON w.id = p.workspace_id AND w.enabled = TRUE
WHERE p.enabled = TRUE
GROUP BY p.workspace_id, p.public_id, p.name;

-- >>> v_projects.sql
-- v_projects
-- Project listing with basic metadata. Workspace-scoped.
CREATE OR REPLACE VIEW v_projects AS
SELECT
  p.workspace_id,
  p.public_id,
  p.slug,
  p.identifier,
  p.name,
  p.description,
  p.color,
  p.is_archived,
  p.started_on,
  p.ended_on,
  p.feature_pages,
  p.feature_timeboxes,
  p.feature_lenses,
  p.feature_calendar,
  p.sort_weight,
  p.updated_at,
  p.created_at
FROM projects p
INNER JOIN workspaces w
  ON w.id = p.workspace_id AND w.enabled = TRUE
WHERE p.enabled = TRUE;

-- >>> v_task_detail.sql
-- v_task_detail
-- Detailed task projection. Uses correlated subqueries for counts to
-- avoid Cartesian products from multiple LEFT JOINs on 1:N tables.
CREATE OR REPLACE VIEW v_task_detail AS
SELECT
  t.workspace_id,
  w.public_id AS workspace_public_id,
  t.public_id,
  p.public_id AS project_public_id,
  p.name AS project_name,
  p.identifier AS project_identifier,
  t.task_number,
  pt.public_id AS parent_task_public_id,
  creator.public_id AS created_by_user_public_id,
  t.title,
  t.description,
  t.visibility,
  t.derived_state,
  t.priority,
  t.due_on,
  t.started_on,
  t.event_on,
  t.completed_at,
  t.archived_at,
  (SELECT COUNT(*) FROM task_constraints c WHERE c.task_id = t.id AND c.enabled = TRUE) AS constraint_count,
  (SELECT COUNT(*) FROM task_constraints c WHERE c.task_id = t.id AND c.enabled = TRUE AND c.satisfied_at IS NOT NULL) AS constraint_satisfied_count,
  (SELECT COUNT(*) FROM task_dependencies d WHERE d.from_task_id = t.id AND d.enabled = TRUE) AS dependency_count,
  (SELECT COUNT(*) FROM task_actors a WHERE a.task_id = t.id AND a.enabled = TRUE) AS actor_count,
  (SELECT COUNT(*) FROM task_labels tl WHERE tl.task_id = t.id AND tl.enabled = TRUE) AS label_count,
  t.sort_weight,
  t.updated_at,
  t.created_at
FROM tasks t
INNER JOIN projects p
  ON p.id = t.project_id AND p.enabled = TRUE
INNER JOIN workspaces w
  ON w.id = t.workspace_id AND w.enabled = TRUE
LEFT JOIN tasks pt
  ON pt.id = t.parent_task_id AND pt.enabled = TRUE
LEFT JOIN users creator
  ON creator.id = t.created_by_user_id AND creator.enabled = TRUE
WHERE t.enabled = TRUE
  AND t.archived_at IS NULL;

-- >>> v_task_list_archived.sql
-- v_task_list_archived
-- Same as v_task_list but only shows archived tasks.
CREATE OR REPLACE VIEW v_task_list_archived AS
SELECT
  t.workspace_id,
  t.id AS task_internal_id,
  t.project_id,
  t.created_by_user_id,
  t.public_id,
  p.public_id AS project_public_id,
  p.name AS project_name,
  p.identifier AS project_identifier,
  t.task_number,
  pt.public_id AS parent_task_public_id,
  t.title,
  t.visibility,
  t.derived_state,
  t.priority,
  t.due_on,
  t.started_on,
  t.event_on,
  t.completed_at,
  t.archived_at,
  t.sort_weight,
  t.updated_at,
  t.created_at,
  assignees.primary_assignee_public_id,
  COALESCE(assignees.assignee_count, 0) AS assignee_count,
  labels.label_ids
FROM tasks t
INNER JOIN projects p
  ON p.id = t.project_id AND p.enabled = TRUE
INNER JOIN workspaces w
  ON w.id = t.workspace_id AND w.enabled = TRUE
LEFT JOIN tasks pt
  ON pt.id = t.parent_task_id AND pt.enabled = TRUE
LEFT JOIN (
  SELECT
    ta.task_id,
    MIN(CASE WHEN rn = 1 THEN u.public_id END) AS primary_assignee_public_id,
    COUNT(*) AS assignee_count
  FROM (
    SELECT ta2.task_id, ta2.user_id,
           ROW_NUMBER() OVER (PARTITION BY ta2.task_id ORDER BY ta2.sort_weight ASC, ta2.id ASC) AS rn
    FROM task_actors ta2
    WHERE ta2.enabled = TRUE AND ta2.role = 'assignee'
  ) ta
  INNER JOIN users u ON u.id = ta.user_id AND u.enabled = TRUE
  GROUP BY ta.task_id
) assignees ON assignees.task_id = t.id
LEFT JOIN (
  SELECT
    tl.task_id,
    GROUP_CONCAT(l.public_id ORDER BY tl.sort_weight ASC, tl.id ASC SEPARATOR ',') AS label_ids
  FROM task_labels tl
  INNER JOIN labels l ON l.id = tl.label_id AND l.enabled = TRUE
  WHERE tl.enabled = TRUE
  GROUP BY tl.task_id
) labels ON labels.task_id = t.id
WHERE t.enabled = TRUE
  AND t.archived_at IS NOT NULL;

-- >>> v_task_list.sql
-- v_task_list
-- Minimal task projection for list / board views.
CREATE OR REPLACE VIEW v_task_list AS
SELECT
  t.workspace_id,
  t.id AS task_internal_id,
  t.project_id,
  t.created_by_user_id,
  t.public_id,
  p.public_id AS project_public_id,
  p.name AS project_name,
  p.identifier AS project_identifier,
  t.task_number,
  pt.public_id AS parent_task_public_id,
  t.title,
  t.visibility,
  t.derived_state,
  t.priority,
  t.due_on,
  t.started_on,
  t.event_on,
  t.completed_at,
  t.archived_at,
  t.sort_weight,
  t.updated_at,
  t.created_at,
  assignees.primary_assignee_public_id,
  COALESCE(assignees.assignee_count, 0) AS assignee_count,
  labels.label_ids
FROM tasks t
INNER JOIN projects p
  ON p.id = t.project_id AND p.enabled = TRUE
INNER JOIN workspaces w
  ON w.id = t.workspace_id AND w.enabled = TRUE
LEFT JOIN tasks pt
  ON pt.id = t.parent_task_id AND pt.enabled = TRUE
LEFT JOIN (
  SELECT
    ta.task_id,
    MIN(CASE WHEN rn = 1 THEN u.public_id END) AS primary_assignee_public_id,
    COUNT(*) AS assignee_count
  FROM (
    SELECT ta2.task_id, ta2.user_id,
           ROW_NUMBER() OVER (PARTITION BY ta2.task_id ORDER BY ta2.sort_weight ASC, ta2.id ASC) AS rn
    FROM task_actors ta2
    WHERE ta2.enabled = TRUE AND ta2.role = 'assignee'
  ) ta
  INNER JOIN users u ON u.id = ta.user_id AND u.enabled = TRUE
  GROUP BY ta.task_id
) assignees ON assignees.task_id = t.id
LEFT JOIN (
  SELECT
    tl.task_id,
    GROUP_CONCAT(l.public_id ORDER BY tl.sort_weight ASC, tl.id ASC SEPARATOR ',') AS label_ids
  FROM task_labels tl
  INNER JOIN labels l ON l.id = tl.label_id AND l.enabled = TRUE
  WHERE tl.enabled = TRUE
  GROUP BY tl.task_id
) labels ON labels.task_id = t.id
WHERE t.enabled = TRUE
  AND t.archived_at IS NULL;

-- >>> v_task_timeline.sql
-- v_task_timeline
-- Timeline of events related to tasks. Merges events with the owning
-- task's public_id so the UI can render without touching internal ids.
CREATE OR REPLACE VIEW v_task_timeline AS
SELECT
  e.workspace_id,
  e.id AS event_id,
  e.public_id,
  t.public_id AS task_public_id,
  p.public_id AS project_public_id,
  actor.public_id AS actor_user_public_id,
  actor.display_name AS actor_display_name,
  e.type,
  e.payload_json,
  e.occurred_at
FROM events e
INNER JOIN workspaces w
  ON w.id = e.workspace_id AND w.enabled = TRUE
LEFT JOIN tasks t
  ON t.id = e.task_id AND t.enabled = TRUE
LEFT JOIN projects p
  ON p.id = t.project_id AND p.enabled = TRUE
LEFT JOIN users actor
  ON actor.id = e.actor_user_id AND actor.enabled = TRUE
WHERE e.enabled = TRUE;

-- >>> v_users.sql
-- v_users
-- Workspace-scoped user projection. Joins workspace_members so the view
-- carries workspace_id for tenant guards. Internal ids are not selected.
CREATE OR REPLACE VIEW v_users AS
SELECT
  wm.workspace_id,
  u.public_id,
  u.email,
  u.display_name,
  u.avatar_url,
  u.locale,
  u.timezone,
  u.country,
  u.theme_preference,
  wm.role AS workspace_role,
  u.last_login_at,
  u.updated_at,
  u.created_at
FROM users u
INNER JOIN workspace_members wm
  ON wm.user_id = u.id AND wm.enabled = TRUE
INNER JOIN workspaces w
  ON w.id = wm.workspace_id AND w.enabled = TRUE
WHERE u.enabled = TRUE;

-- >>> v_workspace_members.sql
-- v_workspace_members
-- Workspace membership joined with user display fields.
CREATE OR REPLACE VIEW v_workspace_members AS
SELECT
  wm.workspace_id,
  wm.public_id,
  u.public_id AS user_public_id,
  u.email,
  u.display_name,
  u.avatar_url,
  wm.role,
  wm.invited_at,
  wm.joined_at,
  wm.updated_at,
  wm.created_at
FROM workspace_members wm
INNER JOIN users u
  ON u.id = wm.user_id AND u.enabled = TRUE
INNER JOIN workspaces w
  ON w.id = wm.workspace_id AND w.enabled = TRUE
WHERE wm.enabled = TRUE;

SET UNIQUE_CHECKS = 1;
SET FOREIGN_KEY_CHECKS = 1;
